widget.solution:
import numpy as np

def dual_basis(B):
    B = np.array(B, dtype=float)
    n = B.shape[0]
    if B.shape != (n, n) or np.linalg.matrix_rank(B) < n:
        raise ValueError("the columns are not a basis")
    D = np.linalg.solve(B, np.eye(n))
    return (np.round(D, 6) + 0.0).tolist()
